themes.lightCss:
@plugin "daisyui/theme" {
  name: "sofiemyr-light";
  default: true;
  prefersdark: false;
  color-scheme: light;
  --color-base-100: oklch(100% 0 0);
  --color-base-200: oklch(96.5% 0.008 245);
  --color-base-300: oklch(90% 0.015 245);
  --color-base-content: oklch(20% 0.025 250);
  --color-primary: oklch(36% 0.14 250);
  --color-primary-content: oklch(99% 0 0);
  --color-secondary: oklch(46% 0.08 245);
  --color-secondary-content: oklch(99% 0 0);
  --color-accent: oklch(62% 0.17 48);
  --color-accent-content: oklch(99% 0 0);
  --color-neutral: oklch(24% 0.03 250);
  --color-neutral-content: oklch(98% 0 0);
  --color-info: oklch(68% 0.12 235);
  --color-info-content: oklch(18% 0.02 235);
  --color-success: oklch(65% 0.15 155);
  --color-success-content: oklch(16% 0.02 155);
  --color-warning: oklch(80% 0.14 85);
  --color-warning-content: oklch(20% 0.02 85);
  --color-error: oklch(62% 0.20 28);
  --color-error-content: oklch(98% 0 0);
  --radius-selector: 0.375rem;
  --radius-field: 0.5rem
  --radius-box: 1.25rem;
  --size-selector: 0.25rem;
  --size-field: 0.25rem;
  --border: 1px;
  --depth: 0;
  --noise: 0;
}

themes.darkCss:
@plugin "daisyui/theme" {
  name: "sofiemyr-dark";
  default: false;
  prefersdark: true;
  color-scheme: dark;
  --color-base-100: oklch(18% 0.02 250);
  --color-base-200: oklch(23% 0.025 250);
  --color-base-300: oklch(30% 0.025 250);
  --color-base-content: oklch(95% 0.01 245);
  --color-primary: oklch(68% 0.16 248);
  --color-primary-content: oklch(15% 0.02 250);
  --color-secondary: oklch(62% 0.10 245);
  --color-secondary-content: oklch(14% 0.02 245);
  --color-accent: oklch(70% 0.16 48);
  --color-accent-content: oklch(20% 0.02 45);
  --color-neutral: oklch(30% 0.025 250);
  --color-neutral-content: oklch(98% 0 0);
  --color-info: oklch(70% 0.11 235);
  --color-info-content: oklch(16% 0.02 235);
  --color-success: oklch(72% 0.14 155);
  --color-success-content: oklch(14% 0.02 155);
  --color-warning: oklch(82% 0.13 85);
  --color-warning-content: oklch(18% 0.02 85);
  --color-error: oklch(70% 0.18 28);
  --color-error-content: oklch(16% 0.02 28);
  --radius-selector: 0.375rem;
  --radius-field: 0.5rem
  --radius-box: 1.25rem;
  --size-selector: 0.25rem;
  --size-field: 0.25rem;
  --border: 1px;
  --depth: 0;
  --noise: 0;
}
